codeExample.bad:
// Shake-to-undo is the only way to trigger undo, with no button
// alternative and no setting to disable the motion trigger
window.addEventListener('devicemotion', (event) => {
  if (isShakeGesture(event)) {
    undoLastAction();
  }
});

codeExample.good:
// Shake-to-undo remains available, but a visible undo button offers
// the same function, and motion detection can be turned off
const motionUndoEnabled = getUserSetting('shakeToUndo');
window.addEventListener('devicemotion', (event) => {
  if (motionUndoEnabled && isShakeGesture(event)) {
    undoLastAction();
  }
});
undoButton.addEventListener('click', () => {
  undoLastAction();
});
